// CWE-22: a path sanitiser never returns a path outside a base directory.
import * as fc from 'fast-check';
import { posix, win32 } from 'node:path';
import { show } from './cwe.ts';
import { securityLaw } from './law.ts';
import type { SecurityLaw } from './law.ts';

/** A hostile path for a law parameter: `law safe(p: PathPayload) => traversal.holds(p)`. Generated by `pathPayloads`. */
export type PathPayload = string & { readonly __tslawsPath: true };

const tokens = [
  '..',
  '.',
  '...',
  '....',
  '%2e%2e',
  '%2E%2E',
  '%252e%252e',
  '..%c0%af',
  '..%ef%bc%8f',
  '\u2025',
  '%u002e%u002e',
];
const separators = [
  '/',
  '\\',
  '//',
  '\\\\',
  '/./',
  '\\/',
  '/\\',
  '%2f',
  '%5c',
  '%252f',
  '..;/',
  '%00/',
  '\0/',
  '\uff0f',
  '%c0%af',
];
const roots = [
  '',
  '/',
  '\\',
  'C:\\',
  'c:/',
  'C:',
  '\\\\server\\share\\',
  '//server/share/',
  '\\\\?\\C:\\',
  '/etc/',
  'file:///',
  '~/',
  '%2f',
  '\0',
];
const names = ['etc', 'passwd', 'win.ini', 'a', 'b', 'secret.txt', '.env', 'index.html', '..%00.png', ''];
const suffixes = ['', '\0', '\0.png', '%00', '%00.png', ' ', '.', '/', '\\', '...', '::$DATA'];

/** The fixed attacks `holds` checks on every call. */
export const pathCorpus: readonly string[] = [
  '../etc/passwd',
  '..\\windows\\win.ini',
  '../../../../../../etc/passwd',
  '....//....//etc/passwd',
  '..././..././etc/passwd',
  '%2e%2e%2f%2e%2e%2fetc%2fpasswd',
  '%252e%252e%252fetc%252fpasswd',
  '..%2fetc',
  '..%5cwindows',
  '/etc/passwd',
  'C:\\Windows\\win.ini',
  'c:/windows/win.ini',
  '\\\\server\\share\\x',
  '//server/share/x',
  'a/../../b',
  'a\\..\\..\\b',
  'file.txt\0.png',
  '..\0/etc',
  '..%00/etc',
  '%c0%ae%c0%ae/etc',
  '..\uff0fetc',
  '\u2025/etc',
  '..;/etc',
  '~/.ssh/id_rsa',
];

/**
 * Paths a sanitiser must not let out of its base: `../`, encoded and double-encoded dots, absolute roots, drive
 * letters, UNC shares, a null byte and Windows separators, mixed.
 */
export function pathPayloads(): fc.Arbitrary<PathPayload> {
  const segment = fc.tuple(fc.constantFrom(...tokens, ...names), fc.constantFrom(...separators)).map(([t, s]) => t + s);
  const built = fc
    .tuple(
      fc.constantFrom(...roots),
      fc.array(segment, { minLength: 0, maxLength: 6 }),
      fc.constantFrom(...names),
      fc.constantFrom(...suffixes),
    )
    .map(([root, parts, name, suffix]) => root + parts.join('') + name + suffix);
  return fc
    .oneof(
      { weight: 8, arbitrary: built },
      { weight: 1, arbitrary: fc.string() },
      { weight: 1, arbitrary: fc.constantFrom(...pathCorpus) },
    )
    .map((p) => p as PathPayload);
}

export interface PathTraversalOptions {
  /** The directory the result must stay inside. */
  base: string;
  /**
   * Which path rules the result is read under. `both` (the default) needs it to stay inside under POSIX and Windows
   * rules, since the same string reaches either. `posix` and `win32` check one.
   */
  flavour?: 'posix' | 'win32' | 'both';
  /** Also read the result as URL-encoded once, for code that decodes the path later. Default false. */
  checkDecoded?: boolean;
}

function inside(flavour: 'posix' | 'win32', base: string, target: string): boolean {
  const p = flavour === 'posix' ? posix : win32;
  const root = p.resolve(base);
  const relative = p.relative(root, p.resolve(root, target));
  return !p.isAbsolute(relative) && relative.split(/[\\/]/)[0] !== '..';
}

function decoded(text: string): string {
  try {
    return decodeURIComponent(text);
  } catch {
    return text;
  }
}

/**
 * CWE-22. `sanitise(input)` must return a path that, resolved against `base`, stays inside it (or throw, or return
 * nothing, to refuse the input). The result may be relative to `base` or absolute. A null byte in the result fails too.
 */
export function pathTraversal(
  sanitise: (input: string) => unknown,
  options: PathTraversalOptions,
): SecurityLaw<PathPayload> {
  const flavours =
    options.flavour === 'both' || options.flavour === undefined ? (['posix', 'win32'] as const) : [options.flavour];
  const read = (result: string, input: string): string | undefined => {
    for (const text of options.checkDecoded === true ? [result, decoded(result)] : [result]) {
      if (text.includes('\0')) return `sanitise(${show(input)}) returned ${show(result)}, which holds a null byte`;
      for (const flavour of flavours)
        if (!inside(flavour, options.base, text))
          return `sanitise(${show(input)}) returned ${show(result)}, outside ${show(options.base)} under ${flavour} rules`;
    }
    return undefined;
  };
  return securityLaw<PathPayload>({
    id: 'path-traversal',
    cwe: ['CWE-22'],
    title: 'a path sanitiser never returns a path outside its base',
    input: pathPayloads(),
    corpus: pathCorpus as readonly PathPayload[],
    verdict: (input) => {
      let result: unknown;
      try {
        result = sanitise(input);
      } catch {
        return undefined;
      }
      if (result === undefined || result === null || result === false) return undefined;
      if (typeof result !== 'string')
        return { detail: `sanitise(${show(input)}) returned ${show(result)}, not a path string` };
      const detail = read(result, input);
      return detail === undefined ? undefined : { detail };
    },
  });
}
